steps.expectedCode:
#![cfg_attr(not(feature = "std"), no_std, no_main)]

#[ink::contract]
mod creature {
    #[ink(storage)]
    pub struct Creature {
        is_awake: bool,
    }

    impl Creature {
        #[ink(constructor)]
        pub fn new() -> Self {
            Self { is_awake: false }
        }

        #[ink(constructor)]
        pub fn default() -> Self {
            Self::new()
        }

        #[ink(message)]
        pub fn is_awake(&self) -> bool {
            self.is_awake
        }

        #[ink(message)]
        pub fn wake_up(&mut self) {
            self.is_awake = !self.is_awake;
        }
    }
}
